  function textSprite(text, { color = "#dff8ff", size = 0.1, bg = "rgba(5,10,16,.72)" } = {}) {
    const c = document.createElement("canvas");
    c.width = 512;
    c.height = 96;
    const g = c.getContext("2d");
    g.fillStyle = bg;
    g.beginPath();
    g.roundRect(2, 2, 508, 92, 16);
    g.fill();
    g.strokeStyle = "rgba(116,230,255,.55)";
    g.lineWidth = 2;
    g.stroke();
    g.fillStyle = color;
    g.font = "600 38px Bahnschrift, Microsoft YaHei";
    g.textAlign = "center";
    g.textBaseline = "middle";
    g.fillText(text, 256, 50);
    const tex = new CanvasTexture(c);
    tex.colorSpace = SRGBColorSpace;
    const sp = new Sprite(new SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false, toneMapped: false }));
    sp.scale.set(size * 5.33, size, 1);
    return sp;
  }

