  function ribShapeGeometry() {
    const loop = [];
    const db = { m: 0.018, p: 0.34, t: 0.083 };
    const t = db.t, m = db.m, p = db.p;
    const N = 24;
    for (let i = 0; i <= N; i++) {
      const x = 0.5 * (1 - Math.cos(Math.PI * i / N));
      const yt = 5 * t * (0.2969 * Math.sqrt(x) - 0.126 * x - 0.3516 * x * x + 0.2843 * x ** 3 - 0.1036 * x ** 4);
      const yc = x < p ? m / (p * p) * (2 * p * x - x * x) : m / (1 - p) ** 2 * (1 - 2 * p + 2 * p * x - x * x);
      loop.push([(0.25 - x) * 0.2, yc + yt]);
    }
    for (let i = N; i >= 0; i--) {
      const x = 0.5 * (1 - Math.cos(Math.PI * i / N));
      const yt = 5 * t * (0.2969 * Math.sqrt(x) - 0.126 * x - 0.3516 * x * x + 0.2843 * x ** 3 - 0.1036 * x ** 4);
      const yc = x < p ? m / (p * p) * (2 * p * x - x * x) : m / (1 - p) ** 2 * (1 - 2 * p + 2 * p * x - x * x);
      loop.push([(0.25 - x) * 0.2, yc - yt]);
    }
    const shape = new three_module_exports.Shape();
    shape.moveTo(loop[0][0], loop[0][1]);
    for (let i = 1; i < loop.length; i++) shape.lineTo(loop[i][0], loop[i][1]);
    const geo = new three_module_exports.ExtrudeGeometry(shape, { depth: 16e-4, bevelEnabled: false });
    geo.rotateY(Math.PI / 2);
    return geo;
  }
