      pad.add(deflector);
      for (const s of [-1, 1]) pad.add(cylinderBetween(new V3(s * 0.22, 0.18, 0), new V3(s * 0.22, 2.6, 0), 0.045, MAT.alu));
      const cross = box(1.1, 0.06, 0.06, MAT.alu);
      cross.position.y = 2.1;
      pad.add(cross);
