  var THRUST = { airdrop: 4.8, cargo: 2.8, solar: 0.75, recon: 1.55, logistics: 4.6, stol: 3.8, eglider: 1.9, dlg: 0, wingtest: 0, rescue: 8.8, triathlon: 6.2, rocket: 0 };
