    ctx.fillStyle = "#5c707b";
    ctx.font = "8px Bahnschrift";
    ctx.textAlign = "left";
    ctx.fillText("L/D", 6, pad.t - 4);
    ctx.fillText("V m/s", W - 45, H - 4);
