    $("#hint").style.display = mode === "showroom" ? "flex" : "none";
    $("#labels").style.display = mode === "showroom" ? "block" : "none";
    $("#airflow-labels").style.display = mode === "airflow" ? "block" : "none";
    $("#stage-badge").style.display = mode === "showroom" ? "flex" : "none";
